INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (101254,1,0,'Use |TInterface\\Icons\\spell_deathknight_strangulate.blp:20|t |cFFFF0000|Hspell:49576|h[Death Grip]|h|r to interrupt Ariden\'s channeling.',41,0,100.0,0,0,60279,120451,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (101282,0,0,'Take care! There is a dark energy emanating from the spirits of this place. We had best not get too close.',12,0,100.0,0,0,0,103594,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (101282,2,0,'It is done. The Dark Riders are defeated.',12,0,100.0,0,0,0,103618,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (101282,3,0,'Now I can reclaim these stolen artifacts and return them to their rightful owners.',12,0,100.0,0,0,0,103619,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (101282,4,0,'You have proven an unexpected ally, $c. The weapon is yours. Let us hope it can turn the tide in this war.',12,0,100.0,0,0,0,103620,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (101282,5,0,'The Dark Riders lost this battle, but I fear they will soon regroup. We had best be gone before they do.',12,0,100.0,0,0,0,103621,0,'LegionCore');
