INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (109698,0,0,'Calydus is here, friend! Council flees! Haha!',14,0,100.0,0,0,66464,115809,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (109698,1,0,'Gul\'dan will use Scepter, Eye, and Book to make portals bigger and stronger. Many, many demons pour through! Friend not want that, I think.',12,0,100.0,0,0,66468,115705,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (109698,2,0,'What if friend trick Gul\'dan into giving up scepter? Then ruin ritual and run away! Haha! This can work, friend!',12,0,100.0,0,0,66469,115708,0,'LegionCore');
