INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (110533,0,0,'Ah, the Book is here at last... borne by one whose meddlesome handiwork I know well! Come to join the winning side, "hero"?',14,0,100.0,0,0,66424,117564,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (110533,1,0,'You have both done well to acquire these artifacts. Your positions in the Shadow Council are all but assured.',12,0,100.0,1,0,66425,117565,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (110533,2,0,'Using the Book, the Eye, and the Scepter, we will amplify this portal and open gateways to countless other demon worlds. The Legion\'s full might will fall upon this pitiful planet!',14,0,100.0,1,0,66426,117566,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (110533,3,0,'I will go through the portal and act as a stabilizing anchor on Argus. You will focus the ritual energy through the scepter, widening the breach and creating a myriad of portals.',14,0,100.0,1,0,66427,117567,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (110533,4,0,'Ahh, I only need ONE of you for the ritual. "Discuss" the matter quickly, and be ready...',14,0,100.0,1,0,66429,117576,0,'LegionCore');
