INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (110556,0,0,'Uh... great master? Which of us is to wield the Scepter?',14,0,100.0,0,0,66428,117568,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (110556,1,0,'It seems we are to be foes after all. Pity, you would have made an excellent servant!',14,0,100.0,0,0,66430,117582,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (110556,2,0,'You have yet to experience my true power!',14,0,100.0,0,0,66422,117586,0,'LegionCore');
