INSERT INTO `gossip_menu_option` (`MenuId`,`OptionIndex`,`OptionIcon`,`OptionText`,`OptionBroadcastTextId`,`OptionType`,`OptionNpcFlag`,`VerifiedBuild`) VALUES (19062,0,0,'You are wrong. I was at the Broken Shore. I saw the demons cut through our men, holy and unholy alike. If we cannot turn the tide now, we are all lost.',102047,1,1,0);
INSERT INTO `gossip_menu_option` (`MenuId`,`OptionIndex`,`OptionIcon`,`OptionText`,`OptionBroadcastTextId`,`OptionType`,`OptionNpcFlag`,`VerifiedBuild`) VALUES (19062,1,0,'I saw how the bodies of your holy warriors lay side by side at the Tomb of Sargeras! The Legion did not yet have such an army, and this time your Light of Heaven alone will not save us from it!',0,1,1,0);
INSERT INTO `gossip_menu_option` (`MenuId`,`OptionIndex`,`OptionIcon`,`OptionText`,`OptionBroadcastTextId`,`OptionType`,`OptionNpcFlag`,`VerifiedBuild`) VALUES (19062,2,0,'Enough! Answer me or die, priest! <Attacking>',0,1,1,0);
